if(state.lastDay===yesterday){state.streak++}
else if(state.lastDay!==''){state.streak=1}
else{state.streak=1}
state.lastDay=t;state.water=0;state.calories=0;state.checklist={};save();
}
}

// ===== RENDER HOME =====
function renderHome(){
document.getElementById('streakBadge').textContent='🔥 '+state.streak+' días';
document.getElementById('levelBadge').textContent=state.level;
document.getElementById('dailyTip').innerHTML='<div style="font-size:.85rem;line-height:1.6;color:var(--text2)">💡 '+TIPS[Math.floor(Math.random()*TIPS.length)]+'</div>';
renderChecklist();detectGaps();
}

function renderChecklist(){
const items=[
{id:'water',label:'Beber 8 vasos de agua',icon:'💧'},
{id:'protein',label:'Consumir proteína en cada comida',icon:'🥩'},
{id:'steps',label:'Caminar 8000+ pasos',icon:'👟'},
{id:'sleep',label:'Dormir 7-9 horas',icon:'😴'},
{id:'train',label:'Completar sesión de entrenamiento',icon:'🏋️'},
{id:'stretch',label:'Estirar 10 minutos',icon:'🧘'},
{id:'sun',label:'15 min de sol directo',icon:'☀️'},
{id:'mindful',label:'5 min meditación/respiración',icon:'🧠'}
];
const el=document.getElementById('dailyChecklist');
el.innerHTML=items.map(i=>{
const checked=state.checklist[i.id]?'checked':'';
const done=state.checklist[i.id]?'done':'';
return `<div class="check-item"><div class="check-box ${checked}" onclick="toggleCheck('${i.id}',this)">${state.checklist[i.id]?'✓':''}</div><span class="check-label ${done}">${i.icon} ${i.label}</span></div>`;
}).join('');
}

function toggleCheck(id,el){
state.checklist[id]=!state.checklist[id];
if(id==='water'&&state.checklist[id])state.water=8;
save();renderChecklist();updateStats();detectGaps();
}

function detectGaps(){
const gaps=[];
if(!state.checklist.water)gaps.push('No has registrado hidratación hoy');
if(!state.checklist.protein)gaps.push('Falta registro de ingesta proteica');
if(!state.checklist.train)gaps.push('Sin sesión de entrenamiento completada');
if(!state.checklist.sleep)gaps.push('No has confirmado descanso adecuado');
if(!state.checklist.steps)gaps.push('Actividad NEAT sin registrar');
if(state.weights.length<3)gaps.push('Registra más pesos para ver tendencia');
if(state.topicsStudied.length<10)gaps.push('Explora la Academia: +990 temas pendientes');
const el=document.getElementById('gapList');
if(gaps.length===0){el.innerHTML='<div class="gap-item" style="color:var(--green)">✅ ¡Todo cubierto! Excelente seguimiento.</div>'}
else{el.innerHTML=gaps.map(g=>`<div class="gap-item">${g}</div>`).join('')}
}

function updateStats(){
document.getElementById('statSessions').textContent=state.sessions;
document.getElementById('statCalories').textContent=state.calories;
document.getElementById('statWater').textContent=state.water;
document.getElementById('statStreak').textContent=state.streak;
document.getElementById('profileLevel').textContent=state.level;
}

// ===== EXERCISES =====
let exFilter='all';
document.querySelectorAll('#trainingTabs .tab').forEach(tab=>{
tab.addEventListener('click',()=>{
document.querySelectorAll('#trainingTabs .tab').forEach(t=>t.classList.remove('active'));
tab.classList.add('active');exFilter=tab.dataset.filter;renderExercises();
});
});

function renderExercises(){
const list=exFilter==='all'?EXERCISES:EXERCISES.filter(e=>e.muscle===exFilter);
const colors={pecho:'#FF6B00',espalda:'#4A9EFF',piernas:'#4CAF50',hombros:'#FFD700',brazos:'#9B59B6',core:'#FF4444'};
document.getElementById('exerciseList').innerHTML=list.map((e,i)=>`
<div class="exercise-item" onclick="openExercise(${EXERCISES.indexOf(e)})">
<div class="exercise-icon">${e.icon}</div>
<div class="exercise-info"><div class="exercise-name">${e.name}</div><div class="exercise-meta">${e.sets} • ${e.difficulty} • ${e.equipment}</div></div>
<div class="muscle-dot" style="background:${colors[e.muscle]}"></div>
</div>`).join('');
}

function openExercise(idx){
const e=EXERCISES[idx];
document.getElementById('exerciseModalContent').innerHTML=`
<div style="text-align:center;margin-bottom:16px"><div style="font-size:3rem">${e.icon}</div><h2 style="font-family:var(--font-display);margin-top:8px">${e.name}</h2><div style="display:flex;gap:6px;justify-content:center;margin-top:8px"><span class="tag">${e.muscle}</span><span class="tag tag-blue">${e.difficulty}</span></div></div>
<p style="font-size:.9rem;line-height:1.6;color:var(--text2);margin-bottom:16px">${e.desc}</p>
<div style="font-weight:700;font-size:.85rem;margin-bottom:8px">Músculos trabajados:</div>
<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px">${e.muscles_worked.map(m=>`<span class="tag tag-green">${m}</span>`).join('')}</div>
<div class="grid-2" style="margin-bottom:16px"><div class="stat-card"><div class="stat-value" style="font-size:1.2rem">${e.sets}</div><div class="stat-label">Series×Reps</div></div><div class="stat-card"><div class="stat-value" style="font-size:1.2rem">${e.equipment}</div><div class="stat-label">Equipo</div></div></div>
<button class="btn btn-primary btn-block" onclick="closeExerciseModal();startSession()">▶ Iniciar Sesión con este ejercicio</button>`;
document.getElementById('exerciseModal').classList.add('active');
}
function closeExerciseModal(){document.getElementById('exerciseModal').classList.remove('active')}
document.getElementById('exerciseModal').addEventListener('click',e=>{if(e.target===document.getElementById('exerciseModal'))closeExerciseModal()});

function renderPrograms(){
document.getElementById('programGrid').innerHTML=PROGRAMS.map(p=>`
<div class="card" style="border-left:3px solid ${p.color};cursor:pointer" onclick="showToast('Programa ${p.name} seleccionado')">
<div style="font-size:1.5rem;margin-bottom:6px">${p.icon}</div>
<div style="font-weight:700;font-size:.85rem">${p.name}</div>
<div style="font-size:.7rem;color:var(--text3);margin-top:2px">${p.desc}</div>
</div>`).join('');
}

// ===== NUTRITION =====
let foodFilter='all';
document.querySelectorAll('#foodTabs .tab').forEach(tab=>{
tab.addEventListener('click',()=>{
document.querySelectorAll('#foodTabs .tab').forEach(t=>t.classList.remove('active'));
tab.classList.add('active');foodFilter=tab.dataset.filter;renderFoods();
});
});

function renderFoods(){
const list=foodFilter==='all'?FOODS:FOODS.filter(f=>f.cat===foodFilter);
document.getElementById('foodList').innerHTML=list.map(f=>`
<div class="food-item">
<div class="food-icon">${f.icon}</div>
<div class="food-info"><div class="food-name">${f.name} <span style="font-size:.65rem;color:var(--text3)">(${f.per})</span></div>
<div class="food-macros"><span class="macro macro-p">P:${f.protein}g</span><span class="macro macro-c">C:${f.carbs}g</span><span class="macro macro-f">G:${f.fat}g</span><span class="macro macro-k">${f.kcal}kcal</span></div></div>
</div>`).join('');
}

function calculateMacros(){
const w=parseFloat(document.getElementById('calcWeight').value)||75;
const goal=document.getElementById('calcGoal').value;
const act=parseFloat(document.getElementById('calcActivity').value);
let bmr=10*w+6.25*175-5*30-5; // Mifflin-St Jeor (male, 30y, 175cm default)
let tdee=bmr*act;
if(goal==='gain')tdee+=300;if(goal==='lose')tdee-=500;
const protein=Math.round(w*2);const fat=Math.round(tdee*0.25/9);const carbs=Math.round((tdee-protein*4-fat*9)/4);
document.getElementById('macroResults').style.display='block';
document.getElementById('macroResults').innerHTML=`
<div class="grid-3" style="text-align:center">
<div class="stat-card"><div class="stat-value" style="font-size:1.3rem">${Math.round(tdee)}</div><div class="stat-label">kcal/día</div></div>
<div class="stat-card"><div class="stat-value" style="font-size:1.3rem;color:var(--orange)">${protein}g</div><div class="stat-label">Proteína</div></div>
<div class="stat-card"><div class="stat-value" style="font-size:1.3rem;color:var(--blue)">${carbs}g</div><div class="stat-label">Carbos</div></div>
</div>
<div style="text-align:center;margin-top:8px"><span class="macro macro-f" style="font-size:.8rem;padding:4px 12px">Grasas: ${fat}g</span></div>
<div style="font-size:.7rem;color:var(--text3);margin-top:8px;text-align:center">Basado en Mifflin-St Jeor • Ajusta según progreso real</div>`;
state.calories=Math.round(tdee);save();updateStats();
}

// ===== MEDIA =====
let mediaFilter='anatomia';
document.querySelectorAll('#mediaTabs .tab').forEach(tab=>{
tab.addEventListener('click',()=>{
document.querySelectorAll('#mediaTabs .tab').forEach(t=>t.classList.remove('active'));
tab.classList.add('active');mediaFilter=tab.dataset.filter;renderMedia();
});
});

function renderMedia(){
const el=document.getElementById('mediaContent');
if(mediaFilter==='anatomia'){
el.innerHTML=`<div class="card"><div style="font-weight:700;margin-bottom:8px">🦴 Sistema Muscular</div><p style="font-size:.8rem;color:var(--text2);line-height:1.5">Explora los 640+ músculos del cuerpo humano. Cada ejercicio activa grupos específicos. Usa las referencias visuales para entender la biomecánica.</p><div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:10px"><span class="tag">Pectorales</span><span class="tag">Deltoides</span><span class="tag">Dorsal</span><span class="tag">Cuádriceps</span><span class="tag">Glúteos</span><span class="tag">Core</span><span class="tag">Bíceps</span><span class="tag">Tríceps</span></div></div>
<div class="card"><div style="font-weight:700;margin-bottom:8px">🎬 Animaciones Recomendadas</div><p style="font-size:.8rem;color:var(--text2)">Muscle & Motion ofrece +2000 vídeos con análisis anatómico 3D lado a lado con ejecución real.</p></div>`;
}else if(mediaFilter==='ejercicios'){
el.innerHTML=EXERCISES.slice(0,8).map(e=>`<div class="exercise-item"><div class="exercise-icon">${e.icon}</div><div class="exercise-info"><div class="exercise-name">${e.name}</div><div class="exercise-meta">${e.muscles_worked.join(', ')}</div></div></div>`).join('');
}else if(mediaFilter==='nutricion'){
el.innerHTML=`<div class="card"><div style="font-weight:700;margin-bottom:8px">🥗 Guía Visual de Nutrición</div><p style="font-size:.8rem;color:var(--text2);line-height:1.5">Cada alimento tiene un perfil único de macronutrientes. Prioriza proteínas completas (aminoácidos esenciales), carbohidratos complejos y grasas insaturadas.</p></div>
<div class="grid-2">${FOODS.slice(0,6).map(f=>`<div class="stat-card"><div style="font-size:1.5rem">${f.icon}</div><div style="font-size:.75rem;font-weight:600;margin-top:4px">${f.name}</div><div style="font-size:.65rem;color:var(--text3)">${f.protein}g prot / ${f.kcal} kcal</div></div>`).join('')}</div>`;
}else{
el.innerHTML=`<div class="card"><div style="font-weight:700;margin-bottom:8px">📦 Recursos de Alojamiento</div><p style="font-size:.8rem;color:var(--text2);margin-bottom:10px">Para subir fotos, vídeos y contenido ilimitado:</p></div>`+
HOSTING_RES.map(r=>`<a class="resource-link" href="${r.url}" target="_blank"><div class="resource-icon">${r.icon}</div><div class="resource-info"><div class="resource-name">${r.name}</div><div class="resource-desc">${r.desc}</div></div><span style="color:var(--text3)">→</span></a>`).join('');
}
document.getElementById('externalResources').innerHTML=RESOURCES.map(r=>`<a class="resource-link" href="${r.url}" target="_blank"><div class="resource-icon">${r.icon}</div><div class="resource-info"><div class="resource-name">${r.name}</div><div class="resource-desc">${r.desc}</div></div><span style="color:var(--text3)">→</span></a>`).join('');
document.getElementById('designResources').innerHTML=DESIGN_RES.map(r=>`<a class="resource-link" href="${r.url}" target="_blank"><div class="resource-icon">${r.icon}</div><div class="resource-info"><div class="resource-name">${r.name}</div><div class="resource-desc">${r.desc}</div></div><span style="color:var(--text3)">→</span></a>`).join('');
}

// ===== COMMUNITY =====
function renderCommunity(){
const allPosts=[...COMMUNITY_POSTS,...state.posts].sort((a,b)=>(b.time||'').localeCompare(a.time||''));
document.getElementById('communityFeed').innerHTML=allPosts.map(p=>`
<div class="post">
<div class="post-header"><div class="post-avatar">${p.avatar}</div><div><div class="post-user">${p.user}</div><div class="post-time">${p.time}</div></div></div>
<div class="post-content">${p.content}</div>
<div class="post-actions"><span class="post-action" onclick="this.innerHTML='❤️ ${p.likes+1}'">🤍 ${p.likes}</span><span class="post-action">💬 ${p.comments}</span><span class="post-action">🔗 Compartir</span></div>
</div>`).join('');
}

function addPost(){
const input=document.getElementById('postInput');
const text=input.value.trim();if(!text)return;
state.posts.unshift({user:'Tú',avatar:'G',time:'ahora',content:text,likes:0,comments:0});
save();renderCommunity();input.value='';showToast('¡Publicación compartida! 🎉');
}

// ===== TIMER =====
let timerInterval=null,timerSeconds=40,timerTotal=40,timerPaused=false,timerStationIdx=0;
const SESSION_EXERCISES=['Sentadilla','Press Banca','Remo Barra','Press Militar','Curl Bíceps','Plancha'];

function startSession(){
timerStationIdx=0;timerSeconds=40;timerTotal=40;timerPaused=false;
document.getElementById('timerOverlay').classList.add('active');
updateTimerDisplay();startTimerInterval();
}

function startTimerInterval(){
clearInterval(timerInterval);
timerInterval=setInterval(()=>{
if(timerPaused)return;
timerSeconds-=0.1;
if(timerSeconds<=0){nextStation()}
updateTimerDisplay();
},100);
}

function updateTimerDisplay(){
const secs=Math.max(0,Math.ceil(timerSeconds));
const m=String(Math.floor(secs/60)).padStart(2,'0');
const s=String(secs%60).padStart(2,'0');
document.getElementById('timerDisplay').textContent=m+':'+s;
document.getElementById('timerExercise').textContent=SESSION_EXERCISES[timerStationIdx]||'Completado';
document.getElementById('timerStation').textContent=`Estación ${timerStationIdx+1}/${SESSION_EXERCISES.length}`;
const ring=document.getElementById('timerRing');
const offset=264*(1-timerSeconds/timerTotal);
ring.style.strokeDashoffset=offset;
// TV sync
document.getElementById('tvTimer').textContent=m+':'+s;
document.getElementById('tvExercise').textContent=SESSION_EXERCISES[timerStationIdx]||'✓';
}

function nextStation(){
timerStationIdx++;
if(timerStationIdx>=SESSION_EXERCISES.length){endSession();return}
timerSeconds=timerStationIdx===SESSION_EXERCISES.length-1?60:40;
timerTotal=timerSeconds;
document.getElementById('timerPhase').textContent=timerStationIdx%2===0?'TRABAJO':'DESCANSO';
if(navigator.vibrate)navigator.vibrate(200);
}

function endSession(){
clearInterval(timerInterval);
document.getElementById('timerOverlay').classList.remove('active');
state.sessions++;state.calories+=350;
state.level=Math.floor(state.sessions/5)+1;
save();updateStats();detectGaps();
showToast('🎉 ¡Sesión completada! +350 kcal estimadas');
if(navigator.vibrate)navigator.vibrate([100,50,100,50,200]);
}

function timerAction(action){
if(action==='pause'){timerPaused=!timerPaused;showToast(timerPaused?'⏸ Pausado':'▶ Reanudado')}
else if(action==='skip'){nextStation()}
else if(action==='exit'){clearInterval(timerInterval);document.getElementById('timerOverlay').classList.remove('active')}
}

// ===== TV MODE =====
function openTVMode(){document.getElementById('tvOverlay').classList.add('active');startSession()}
function closeTV(){document.getElementById('tvOverlay').classList.remove('active');clearInterval(timerInterval);document.getElementById('timerOverlay').classList.remove('active')}

// ===== ACADEMY (1000 TOPICS) =====
const AREAS=['Fuerza','Hipertrofia','Resistencia','Movilidad','Nutrición','Recuperación','Psicología','Biomecánica','Fisiología','Programación'];
const MUSCLES=['Pecho','Espalda','Piernas','Hombros','Brazos','Core','Glúteos','Cadena Posterior','Full Body','Unilateral'];
const METHODS=['Sobrecarga Progresiva','Periodización','Tempo','Drop Sets','Superseries','Circuitos','Pliometría','Isométricos','Excéntricos','Cluster Sets'];

function generateTopics(){
const topics=[];let n=1;
for(let a=0;a<AREAS.length;a++){for(let m=0;m<MUSCLES.length;m++){for(let me=0;me<METHODS.length;me++){
topics.push({id:n,text:`${AREAS[a]}: ${MUSCLES[m]} — ${METHODS[me]}`,studied:state.topicsStudied.includes(n)});n++;
}}}
return topics;
}
let allTopics=generateTopics();

function renderTopics(filter=''){
const filtered=filter?allTopics.filter(t=>t.text.toLowerCase().includes(filter.toLowerCase())):allTopics;
const page=filtered.slice(0,100);
document.getElementById('topicList').innerHTML=page.map(t=>`
<div class="topic-item ${t.studied?'studied':''}" onclick="toggleTopic(${t.id})">
<span class="topic-num">#${t.id}</span>
<span style="flex:1;font-size:.78rem">${t.text}</span>
<span class="topic-check">${t.studied?'✓':''}</span>
</div>`).join('');
document.getElementById('topicCount').textContent=state.topicsStudied.length;
document.getElementById('topicProgress').style.width=(state.topicsStudied.length/10)+'%';
}

function toggleTopic(id){
const idx=state.topicsStudied.indexOf(id);
if(idx>-1)state.topicsStudied.splice(idx,1);else state.topicsStudied.push(id);
allTopics[id-1].studied=!allTopics[id-1].studied;
save();renderTopics(document.getElementById('topicSearch').value);
}

function filterTopics(){renderTopics(document.getElementById('topicSearch').value)}
function randomTopic(){const id=Math.floor(Math.random()*1000)+1;showToast('🎲 Tema #'+id+': '+allTopics[id-1].text)}
function openAcademy(){document.getElementById('academyOverlay').classList.add('active');renderTopics()}
function closeAcademy(){document.getElementById('academyOverlay').classList.remove('active')}
document.getElementById('academyOverlay').addEventListener('click',e=>{if(e.target===document.getElementById('academyOverlay'))closeAcademy()});

// ===== WEIGHT CHART =====
function addWeight(){
const w=parseFloat(document.getElementById('weightInput').value);
if(!w)return;
state.weights.push({date:today(),weight:w});
save();document.getElementById('weightInput').value='';drawChart();showToast('Peso registrado: '+w+' kg');
}

function drawChart(){
const canvas=document.getElementById('weightChart');
const ctx=canvas.getContext('2d');
ctx.clearRect(0,0,400,150);
if(state.weights.length<2){ctx.fillStyle='#8A7D6D';ctx.font='12px Inter';ctx.textAlign='center';ctx.fillText('Registra al menos 2 pesos para ver gráfica',200,75);return}
const weights=state.weights.map(w=>w.weight);
const min=Math.min(...weights)-2,max=Math.max(...weights)+2;
const range=max-min||1;
ctx.strokeStyle='#FF6B00';ctx.lineWidth=2;ctx.beginPath();
weights.forEach((w,i)=>{
const x=20+i*(360/(weights.length-1));
const y=130-((w-min)/range)*110;
if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
});
ctx.stroke();
weights.forEach((w,i)=>{
const x=20+i*(360/(weights.length-1));
const y=130-((w-min)/range)*110;
ctx.fillStyle='#FF6B00';ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();
ctx.fillStyle='#C4B8A8';ctx.font='9px Inter';ctx.textAlign='center';ctx.fillText(w+'kg',x,y-10);
});
}

// ===== UTILS =====
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function toggleSetting(el){el.classList.toggle('checked')}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='goalgo-gym-data.json';a.click();showToast('📥 Datos exportados')}
function resetData(){if(confirm('¿Borrar todos los datos?')){localStorage.removeItem('goalgo');location.reload()}}

function createParticles(){
const el=document.getElementById('particles');
for(let i=0;i<15;i++){
const p=document.createElement('div');p.className='particle';
p.style.left=Math.random()*100+'%';
p.style.animationDelay=Math.random()*8+'s';
p.style.animationDuration=(6+Math.random()*6)+'s';
el.appendChild(p);
}
}

// ESC key
document.addEventListener('keydown',e=>{
if(e.key==='Escape'){
closeExerciseModal();closeAcademy();closeTV();
document.getElementById('timerOverlay').classList.remove('active');clearInterval(timerInterval);
}
});

// Init chart
setTimeout(drawChart,100);
</script>
</body>
</html>'''

# Save to file
with open('goalgo_gym.html', 'w', encoding='utf-8') as f:
    f.write(html_content)

print(f"✅ Archivo HTML generado: goalgo_gym.html")
print(f"📊 Tamaño: {len(html_content):,} caracteres")
print(f"📐 Líneas: {html_content.count(chr(10)):,}")
print(f"\n📋 SECCIONES INCLUIDAS:")
sections = ["Home (Dashboard + Gap Detector IA + Checklist)", "Entrenamiento (20 ejercicios + 6 programas + filtros)", 
            "Nutrición (25 alimentos + calculadora macros)", "Biblioteca Visual (anatomía + recursos + diseño + hosting)",
            "Comunidad (feed + desafíos + modo TV)", "Perfil (peso + gráfica + ajustes + export)",
            "Timer de Sesión (6 estaciones + anillo SVG)", "Academia (1000 temas generados)", 
            "Modo TV (proyección fullscreen)", "PWA-ready (meta tags + offline structure)"]
for i, s in enumerate(sections, 1):
    print(f"  {i}. {s}")
"}

