$('#calcBtn').addEventListener('click',()=>{const a=+$('#mAge').value||25,h=+$('#mHeight').value||170,w=+$('#mWeight').value||70,act=+$('#mAct').value,goal=+$('#mGoal').value;let bmr=S.sex==='m'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161;const tdee=Math.round(bmr*act);const total=tdee+goal;const p=Math.round(w*(goal>0?1.9:goal<0?2.2:1.8));const f=Math.round(total*0.25/9);const c=Math.max(0,Math.round((total-p*4-f*9)/4));$('#macroRes').classList.remove('hidden');animNum($('#rKcal'),total,700,true);$('#gP').textContent=p+'g';$('#gC').textContent=c+'g';$('#gF').textContent=f+'g';const pk=p*4,ck=c*4,fk=f*9;setTimeout(()=>{$('#bP').style.width=(pk/total*100)+'%';$('#bC').style.width=(ck/total*100)+'%';$('#bF').style.width=(fk/total*100)+'%';},60);S.macro=total;save('macro');updKcal();renderAch();toast('Plan calculado con Mifflin-St Jeor','🧮');});
