function renderChart(){const box=$('#chart');const ws=S.weight.slice().sort((a,b)=>a.d-b.d);if(ws.length<2){box.innerHTML='<div class="chart-empty">Registra al menos 2 pesos para ver tu curva.</div>';return;}const W=300,H=120,P=14;const vals=ws.map(x=>x.w);let mn=Math.min(...vals),mx=Math.max(...vals);if(mn===mx){mn-=1;mx+=1;}mn-=0.5;mx+=0.5;const pts=ws.map((x,i)=>[P+i*(W-2*P)/(ws.length-1),H-P-(x.w-mn)/(mx-mn)*(H-2*P)]);const poly=pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ');const area=`M${pts[0][0].toFixed(1)},${H-P} L`+pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' L')+` L${pts[pts.length-1][0].toFixed(1)},${H-P} Z`;const dots=pts.map(p=>`<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="3" fill="#ff7a1c"/>`).join('');box.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff7a1c" stop-opacity=".4"/><stop offset="1" stop-color="#ff7a1c" stop-opacity="0"/></linearGradient></defs><path d="${area}" fill="url(#ag)"/><polyline points="${poly}" fill="none" stroke="#ff9a45" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>${dots}</svg>`;}
