// ===== TIMER =====
let timerInterval=null,timerSeconds=40,timerTotal=40,timerPaused=false,timerStationIdx=0;
const SESSION_EXERCISES=['Sentadilla','Press Banca','Remo Barra','Press Militar','Curl Bíceps','Plancha'];

function startSession(){
timerStationIdx=0;timerSeconds=40;timerTotal=40;timerPaused=false;
document.getElementById('timerOverlay').classList.add('active');
updateTimerDisplay();startTimerInterval();
}

function startTimerInterval(){
clearInterval(timerInterval);
timerInterval=setInterval(()=>{
if(timerPaused)return;
timerSeconds-=0.1;
if(timerSeconds<=0){nextStation()}
updateTimerDisplay();
},100);
}

function updateTimerDisplay(){
const secs=Math.max(0,Math.ceil(timerSeconds));
const m=String(Math.floor(secs/60)).padStart(2,'0');
const s=String(secs%60).padStart(2,'0');
document.getElementById('timerDisplay').textContent=m+':'+s;
document.getElementById('timerExercise').textContent=SESSION_EXERCISES[timerStationIdx]||'Completado';
document.getElementById('timerStation').textContent=`Estación ${timerStationIdx+1}/${SESSION_EXERCISES.length}`;
const ring=document.getElementById('timerRing');
const offset=264*(1-timerSeconds/timerTotal);
ring.style.strokeDashoffset=offset;
// TV sync
document.getElementById('tvTimer').textContent=m+':'+s;
document.getElementById('tvExercise').textContent=SESSION_EXERCISES[timerStationIdx]||'✓';
}

function nextStation(){
timerStationIdx++;
if(timerStationIdx>=SESSION_EXERCISES.length){endSession();return}
timerSeconds=timerStationIdx===SESSION_EXERCISES.length-1?60:40;
timerTotal=timerSeconds;
document.getElementById('timerPhase').textContent=timerStationIdx%2===0?'TRABAJO':'DESCANSO';
if(navigator.vibrate)navigator.vibrate(200);
}

function endSession(){
clearInterval(timerInterval);
document.getElementById('timerOverlay').classList.remove('active');
state.sessions++;state.calories+=350;
state.level=Math.floor(state.sessions/5)+1;
save();updateStats();detectGaps();
showToast('🎉 ¡Sesión completada! +350 kcal estimadas');
if(navigator.vibrate)navigator.vibrate([100,50,100,50,200]);
}

function timerAction(action){
if(action==='pause'){timerPaused=!timerPaused;showToast(timerPaused?'⏸ Pausado':'▶ Reanudado')}
else if(action==='skip'){nextStation()}
else if(action==='exit'){clearInterval(timerInterval);document.getElementById('timerOverlay').classList.remove('active')}
}

// ===== TV MODE =====
function openTVMode(){document.getElementById('tvOverlay').classList.add('active');startSession()}
function closeTV(){document.getElementById('tvOverlay').classList.remove('active');clearInterval(timerInterval);document.getElementById('timerOverlay').classList.remove('active')}

// ===== ACADEMY (1000 TOPICS) =====
const AREAS=['Fuerza','Hipertrofia','Resistencia','Movilidad','Nutrición','Recuperación','Psicología','Biomecánica','Fisiología','Programación'];
const MUSCLES=['Pecho','Espalda','Piernas','Hombros','Brazos','Core','Glúteos','Cadena Posterior','Full Body','Unilateral'];
const METHODS=['Sobrecarga Progresiva','Periodización','Tempo','Drop Sets','Superseries','Circuitos','Pliometría','Isométricos','Excéntricos','Cluster Sets'];

function generateTopics(){
const topics=[];let n=1;
for(let a=0;a<AREAS.length;a++){for(let m=0;m<MUSCLES.length;m++){for(let me=0;me<METHODS.length;me++){
topics.push({id:n,text:`${AREAS[a]}: ${MUSCLES[m]} — ${METHODS[me]}`,studied:state.topicsStudied.includes(n)});n++;
}}}
return topics;
}
let allTopics=generateTopics();

function renderTopics(filter=''){
const filtered=filter?allTopics.filter(t=>t.text.toLowerCase().includes(filter.toLowerCase())):allTopics;
const page=filtered.slice(0,100);
document.getElementById('topicList').innerHTML=page.map(t=>`
<div class="topic-item ${t.studied?'studied':''}" onclick="toggleTopic(${t.id})">
<span class="topic-num">#${t.id}</span>
<span style="flex:1;font-size:.78rem">${t.text}</span>
<span class="topic-check">${t.studied?'✓':''}</span>
</div>`).join('');
document.getElementById('topicCount').textContent=state.topicsStudied.length;
document.getElementById('topicProgress').style.width=(state.topicsStudied.length/10)+'%';
}

function toggleTopic(id){
const idx=state.topicsStudied.indexOf(id);
if(idx>-1)state.topicsStudied.splice(idx,1);else state.topicsStudied.push(id);
allTopics[id-1].studied=!allTopics[id-1].studied;
save();renderTopics(document.getElementById('topicSearch').value);
}

function filterTopics(){renderTopics(document.getElementById('topicSearch').value)}
function randomTopic(){const id=Math.floor(Math.random()*1000)+1;showToast('🎲 Tema #'+id+': '+allTopics[id-1].text)}
function openAcademy(){document.getElementById('academyOverlay').classList.add('active');renderTopics()}
function closeAcademy(){document.getElementById('academyOverlay').classList.remove('active')}
document.getElementById('academyOverlay').addEventListener('click',e=>{if(e.target===document.getElementById('academyOverlay'))closeAcademy()});

// ===== WEIGHT CHART =====
function addWeight(){
const w=parseFloat(document.getElementById('weightInput').value);
if(!w)return;
state.weights.push({date:today(),weight:w});
save();document.getElementById('weightInput').value='';drawChart();showToast('Peso registrado: '+w+' kg');
}

function drawChart(){
const canvas=document.getElementById('weightChart');
const ctx=canvas.getContext('2d');
ctx.clearRect(0,0,400,150);
if(state.weights.length<2){ctx.fillStyle='#8A7D6D';ctx.font='12px Inter';ctx.textAlign='center';ctx.fillText('Registra al menos 2 pesos para ver gráfica',200,75);return}
const weights=state.weights.map(w=>w.weight);
const min=Math.min(...weights)-2,max=Math.max(...weights)+2;
const range=max-min||1;
ctx.strokeStyle='#FF6B00';ctx.lineWidth=2;ctx.beginPath();
weights.forEach((w,i)=>{
const x=20+i*(360/(weights.length-1));
const y=130-((w-min)/range)*110;
if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
});
ctx.stroke();
weights.forEach((w,i)=>{
const x=20+i*(360/(weights.length-1));
const y=130-((w-min)/range)*110;
ctx.fillStyle='#FF6B00';ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();
ctx.fillStyle='#C4B8A8';ctx.font='9px Inter';ctx.textAlign='center';ctx.fillText(w+'kg',x,y-10);
});
}

// ===== UTILS =====
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
function toggleSetting(el){el.classList.toggle('checked')}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='goalgo-gym-data.json';a.click();showToast('📥 Datos exportados')}
function resetData(){if(confirm('¿Borrar todos los datos?')){localStorage.removeItem('goalgo');location.reload()}}

function createParticles(){
const el=document.getElementById('particles');
for(let i=0;i<15;i++){
const p=document.createElement('div');p.className='particle';
p.style.left=Math.random()*100+'%';
p.style.animationDelay=Math.random()*8+'s';
p.style.animationDuration=(6+Math.random()*6)+'s';
el.appendChild(p);
}
}

// ESC key
document.addEventListener('keydown',e=>{
if(e.key==='Escape'){
closeExerciseModal();closeAcademy();closeTV();
document.getElementById('timerOverlay').classList.remove('active');clearInterval(timerInterval);
}
});

// Init chart
setTimeout(drawChart,100);
</script>
</body>
</html>'''

# Save to file
with open('goalgo_gym.html', 'w', encoding='utf-8') as f:
    f.write(html_content)

print(f"✅ Archivo HTML generado: goalgo_gym.html")
print(f"📊 Tamaño: {len(html_content):,} caracteres")
print(f"📐 Líneas: {html_content.count(chr(10)):,}")
print(f"\n📋 SECCIONES INCLUIDAS:")
sections = ["Home (Dashboard + Gap Detector IA + Checklist)", "Entrenamiento (20 ejercicios + 6 programas + filtros)", 
            "Nutrición (25 alimentos + calculadora macros)", "Biblioteca Visual (anatomía + recursos + diseño + hosting)",
            "Comunidad (feed + desafíos + modo TV)", "Perfil (peso + gráfica + ajustes + export)",
            "Timer de Sesión (6 estaciones + anillo SVG)", "Academia (1000 temas generados)", 
            "Modo TV (proyección fullscreen)", "PWA-ready (meta tags + offline structure)"]
for i, s in enumerate(sections, 1):
    print(f"  {i}. {s}")
"}

