const C=2*Math.PI*54;
let TM={st:[],i:0,ph:'work',rem:0,tot:0,iv:null,run:false,done:false};
function startTimer(list,dw,dr){TM.st=list.map(s=>typeof s==='string'?{n:s,w:dw||45,r:dr||15}:{n:s.n,w:s.w||(dw||45),r:s.r||(dr||15)});TM.i=0;TM.done=false;setPhase('work');TM.run=true;renderTimerShell();openOv('timerOv');clearInterval(TM.iv);TM.iv=setInterval(tick,100);}
function setPhase(p){TM.ph=p;TM.tot=p==='work'?TM.st[TM.i].w:TM.st[TM.i].r;TM.rem=TM.tot;}
function tick(){if(!TM.run||TM.done)return;TM.rem-=0.1;if(TM.rem<=0){vib(140);if(TM.ph==='work'){if(TM.i>=TM.st.length-1){endTimer();return;}setPhase('rest');}else{TM.i++;setPhase('work');}}renderTimerDyn();}
function vib(p){try{navigator.vibrate&&navigator.vibrate(p);}catch(e){}}
function renderTimerShell(){$('#timerOv').classList.toggle('rest',TM.ph==='rest');$('#tWrap').innerHTML=`<div class="t-phase" id="tPhase"></div><div class="t-station" id="tStation"></div><div class="ring-wrap"><svg viewBox="0 0 120 120"><circle class="ring-bg" cx="60" cy="60" r="54"/><circle class="ring-fg" id="tRing" cx="60" cy="60" r="54" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="0"/></svg><div class="t-big"><div class="num" id="tBig">0</div><small id="tTot"></small></div></div><div class="t-count" id="tCount"></div><div class="t-ctrls"><button id="tExit">${svg('x')}</button><button class="tp" id="tPause">${svg('pause')}</button><button id="tSkip">${svg('chev')}</button></div>`;$('#tExit').onclick=()=>{clearInterval(TM.iv);closeOv('timerOv');};$('#tPause').onclick=function(){TM.run=!TM.run;this.innerHTML=TM.run?svg('pause'):svg('play');};$('#tSkip').onclick=()=>{TM.rem=0;};renderTimerDyn();}
function renderTimerDyn(){$('#timerOv').classList.toggle('rest',TM.ph==='rest');$('#tPhase').textContent=TM.ph==='work'?'TRABAJO':'DESCANSO';$('#tStation').textContent=TM.st[TM.i].n;$('#tBig').textContent=Math.max(0,Math.ceil(TM.rem));$('#tTot').textContent='/ '+TM.tot+'s';$('#tCount').textContent='ESTACIÓN '+(TM.i+1)+' / '+TM.st.length;$('#tRing').setAttribute('stroke-dashoffset',(C*(1-TM.rem/TM.tot)).toFixed(1));}
function endTimer(){clearInterval(TM.iv);TM.done=true;TM.run=false;vib([100,60,100,60,200]);const work=TM.st.reduce((a,s)=>a+s.w,0);const kcal=Math.round(work*0.16);S.sess++;save('sess');updLevel();renderAch();$('#tWrap').innerHTML=`<div class="t-sum"><div style="font-size:46px">🏁</div><h3>¡Sesión completa!</h3><p class="muted" style="margin-top:6px">Has terminado ${TM.st.length} estaciones.</p><div class="tstats"><div class="ts"><div class="num">${TM.st.length}</div><div class="tl">Estaciones</div></div><div class="ts"><div class="num">${Math.round(work/60)}</div><div class="tl">Min trabajo</div></div><div class="ts"><div class="num">~${kcal}</div><div class="tl">Kcal</div></div></div><div class="ex-btns" style="justify-content:center"><button class="btn btn-ghost" id="tRepeat">${svg('play')}Repetir</button><button class="btn btn-primary" id="tClose">Cerrar</button></div></div>`;$('#tRepeat').onclick=()=>startTimer(TM.st.map(s=>({n:s.n,w:s.w,r:s.r})));$('#tClose').onclick=()=>closeOv('timerOv');toast('Sesión registrada · +120 XP','🏆');}
